/* 3D Glass Cards */
.sf-hero-card {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 15px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.5);
  padding: 20px;
  color: #ffffff;
}

.sf-hcard {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 10px;
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.3);
  padding: 15px;
  margin: 10px;
  color: #ffffff;
}

/* Horizontal Scroll Rows */
.sf-hscroll {
  display: flex;
  overflow-x: auto;
  padding: 10px;
  scrollbar-width: thin;
}

.sf-hscroll::-webkit-scrollbar {
  height: 8px;
}

.sf-hscroll::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.5);
  border-radius: 10px;
}

/* Gradient Hero Banners */
.sf-hero-card {
  background: linear-gradient(135deg, rgba(0, 123, 255, 0.8), rgba(0, 255, 123, 0.8));
}

/* High-Contrast Buttons */
#view-1 .btn,
#view-2 .btn,
#view-3 .btn,
#view-4 .btn,
#view-detail .btn {
  background-color: #ff4081;
  color: #ffffff;
  border: none;
  border-radius: 5px;
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

#view-1 .btn:hover,
#view-2 .btn:hover,
#view-3 .btn:hover,
#view-4 .btn:hover,
#view-detail .btn:hover {
  background-color: #e91e63;
}

