window.onSearchInput = function(q) {
  const goals = document.querySelectorAll('#goal-list .sf-list-row');
  goals.forEach(goal => {
    const title = goal.textContent.toLowerCase();
    goal.style.display = title.includes(q.toLowerCase()) ? 'block' : 'none';
  });
};

